 263	\begin{lemma}[Consistency from closeness with one projective family; Fact 4.14 in \cite{Natarajan2018NEEXP}]\label{fact:agreement-one-sided}
 264		\notready
 265		\uses{def:consistency, def:povm-distance}
 266		Let $\{A^x_a\}$ and $\{B^x_a\}$ be POVMs. If $A^x_a \ot \Id_B \approx_\delta \Id_A \ot B^x_a$ and either $\{A^x_a\}$ or $\{B^x_a\}$ is a projective measurement, then $A^x_a \ot \Id_B \simeq_{\delta^{1/2}} \Id_A \ot B^x_a$.
 267	\end{lemma}
 268	\begin{proof}
 269		\uses{lem:distance-projective-left-square-root}
 270		Stated in the source without proof; it is the last part of Facts 4.13 and 4.14 of \cite{Natarajan2018NEEXP}. Write the off-diagonal mass $\sum_{a \ne b} \bra{\psi} A^x_a \ot B^x_b \ket{\psi}$ as an inner product involving $(A^x_a \ot \Id - \Id \ot B^x_a)\ket{\psi}$, using projectivity of one of the two families, and apply the Cauchy--Schwarz inequality; this route costs a square root in the error. Only the branch in which $\{A^x_a\}$ is the projective family is available, as Lemma~\ref{lem:agreement-projective-left}; the branch in which only $\{B^x_a\}$ is projective is still open.
 271	\end{proof}
