 273	\begin{lemma}[Left-projective branch of Lemma~\ref{fact:agreement-one-sided}]\label{lem:agreement-projective-left}
 274		\lean{MIPStarRE.QPBT.consistencyDefect_le_sqrt_of_projective_left}
 275		\leanok
 276		\uses{def:consistency, def:povm-distance}
 277		This entry states only the branch of Lemma~\ref{fact:agreement-one-sided} in which the left family is the projective one; it is not the full disjunctive statement of the source. Let $\mu$ be a probability distribution on $\mathcal X$, let $\ket{\psi}$ be a unit vector, and let $\{A^x_a\}$ be a projective measurement for every $x$. Then
 278		\[
 279			\E_x \sum_{a \ne b} \bra{\psi} A^x_a \ot B^x_b \ket{\psi}
 280			\leq \sqrt{2\, \E_x \sum_a \bigl\lVert (A^x_a \ot \Id - \Id \ot B^x_a)\ket{\psi} \bigr\rVert^2}\,;
 281		\]
 282		in particular, if $A^x_a \ot \Id_B \approx_\delta \Id_A \ot B^x_a$, then $A^x_a \ot \Id_B \simeq_{(2\delta)^{1/2}} \Id_A \ot B^x_a$.
 283	\end{lemma}
 284	\begin{proof}
 285		\leanok
 286		\uses{lem:distance-projective-left-square-root, lem:distance-averaged-square-root}
 287		Apply the pointwise estimate of Lemma~\ref{lem:distance-projective-left-square-root} at each question $x$, then average over $x$ with Lemma~\ref{lem:distance-averaged-square-root}.
 288	\end{proof}
