 308	\begin{lemma}[Multiplying by function-indexed operators]\label{fact:add-a-proj2}
 309		\lean{MIPStarRE.QPBT.opFamilyDistSq_mul_funIndexed_le}
 310		\leanok
 311		\uses{def:povm-distance}
 312		Let $\mathcal X, \mathcal A$ be finite sets, and let $\mathcal G$ be a set of functions $g \colon \mathcal X \to \mathcal A$. Let $\{A^x_a\}$ and $\{B^x_a\}$ be POVMs indexed by $\mathcal X$ with outcomes in $\mathcal A$. Let $\{S^x_g\}_{x \in \mathcal X,\, g \in \mathcal G}$ be a set of operators such that for all $x \in \mathcal X$, $\sum_g (S^x_g)^\dagger S^x_g \le \Id$. If $A^x_a \approx_\delta B^x_a$ on average over $x$, then $S^x_g A^x_{g(x)} \approx_\delta S^x_g B^x_{g(x)}$.
 313	\end{lemma}
 314	\begin{proof}
 315		\leanok
 316		\uses{lem:distance-function-indexed-contraction}
 317		Expand the left-hand side and group the sum over $g$ according to the value $a = g(x)$:
 318		\[
 319			\E_x \sum_g \bigl\lVert S^x_g (A^x_{g(x)} - B^x_{g(x)})\, \ket{\psi} \bigr\rVert^2
 320			= \E_x \sum_a \bra{\psi} (A^x_a - B^x_a)^\dagger \Bigl( \sum_{g\,:\,g(x)=a} (S^x_g)^\dagger S^x_g \Bigr) (A^x_a - B^x_a) \ket{\psi}\,.
 321		\]
 322		% The source (references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:347-361) ends with
 323		% "at most delta by assumption"; under def:povm-distance the hypothesis only bounds this
 324		% quantity by O(delta), which is what the conclusion requires.
 325		Since $\sum_{g\,:\,g(x)=a} (S^x_g)^\dagger S^x_g \le \sum_g (S^x_g)^\dagger S^x_g \le \Id$, this is at most $\E_x \sum_a \lVert (A^x_a - B^x_a)\ket{\psi} \rVert^2$, which is $O(\delta)$ by the hypothesis $A^x_a \approx_\delta B^x_a$ (Definition~\ref{def:povm-distance}); this is exactly the bound required for the conclusion.
 326	\end{proof}
