 328	\begin{lemma}[Absorbing an approximating family into a projective sum]\label{lem:cool-closeness-fact}
 329		\lean{MIPStarRE.QPBT.opDistSq_sum_sub_mul_le_of_projective}
 330		\leanok
 331		\uses{def:povm-distance, def:povm-conventions}
 332		Let $\mathcal X$ and $\mathcal A$ be finite sets and $\mu$ a distribution on $\mathcal X$. Let $\{A^x_a\}_{a \in \mathcal A}$ be a projective measurement and let $\{B^x_a\}_{a \in \mathcal A}$ be a set of matrices. If $A^x_a \approx_\delta B^x_a$, then for all subsets $S \subseteq \mathcal A$ we have
 333		\[
 334			\sum_{a \in S} A^x_a \approx_\delta \sum_{a \in S} A^x_a \cdot B^x_a\,.
 335		\]
 336	\end{lemma}
 337	\begin{proof}
 338		\leanok
 339		\uses{lem:distance-projective-orthogonality,
 340			lem:distance-projective-sum}
 341		By projectivity, $\sum_{a \in S} (A^x_a - A^x_a B^x_a) = \sum_{a \in S} A^x_a (A^x_a - B^x_a)$. Expanding the squared norm of the corresponding vector, the cross terms for distinct $a \ne a' \in S$ vanish because $A^x_a A^x_{a'} = 0$, so
 342		\begin{align*}
 343			\E_x \Bigl\lVert \sum_{a \in S} \bigl(A^x_a - A^x_a B^x_a\bigr) \ket{\psi} \Bigr\rVert^2
 344			&= \E_x \sum_{a \in S} \bra{\psi} (A^x_a - B^x_a)^\dagger A^x_a (A^x_a - B^x_a) \ket{\psi}\\
 345			&\le \E_x \sum_a \lVert (A^x_a - B^x_a)\ket{\psi} \rVert^2\,,
 346		\end{align*}
 347		% Under def:povm-distance the closeness hypothesis bounds the final quantity by
 348		% O(delta), not by delta itself; the source
 349		% (references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:364-380) elides this.
 350		where the last step uses $A^x_a \le \Id$. All expectations are taken according to $\mu$, and the last quantity is $O(\delta)$ by the assumption $A^x_a \approx_\delta B^x_a$ (Definition~\ref{def:povm-distance}), which is the bound required for the conclusion.
 351	\end{proof}
