 381	\begin{lemma}[Data processing; Fact 4.26 in \cite{Natarajan2018NEEXP}]\label{fact:data-processing}
 382		\lean{MIPStarRE.QPBT.consistencyDefect_postprocess_le}
 383		\leanok
 384		\uses{def:consistency, def:bracket}
 385		Suppose $A^x_a \ot \Id_B \simeq_\delta \Id_A \ot B^x_a$. Then for any function $f$ on the outcome set,
 386		\[
 387			A^x_{[f(\cdot)=b]} \ot \Id_B \simeq_\delta \Id_A \ot B^x_{[f(\cdot)=b]}\,.
 388		\]
 389	\end{lemma}
 390	\begin{proof}
 391		\leanok
 392		\uses{def:distance-state-quadratic-form,
 393			lem:distance-consistency-term, lem:distance-point-defect,
 394			def:distance-left-placed-measurement,
 395			def:distance-right-placed-measurement,
 396			lem:distance-placed-product-qform,
 397			lem:distance-postprocess-overlap}
 398		Stated in the source without proof; it is Fact 4.26 of \cite{Natarajan2018NEEXP}. Every off-diagonal pair $(b, b')$ with $b \ne b'$ of the post-processed families pulls back to pairs $(a, a')$ with $f(a) = b \ne b' = f(a')$, and in particular $a \ne a'$. Coarse-graining therefore only merges terms of the off-diagonal sum, so the post-processed off-diagonal mass is at most the original one.
