 401	The state-dependent distance is the right tool for reasoning about the closeness of measurement operators in a strategy. The following lemma converts joint consistency with a single projective measurement into an approximate commutation relation.
 402	
 403	\begin{lemma}[Approximate commutation from joint consistency]\label{lem:commutation-analysis}
 404		\lean{MIPStarRE.QPBT.opDistSq_commutator_le}
 405		\leanok
 406		\uses{def:povm-distance, def:povm-conventions}
 407		Let $\{A^x_{a,\,b}\}$, $\{B^x_{a,\,b,\,c}\}$, $\{C^x_{a,\,c}\}$ be POVMs. Suppose $\{B^x_{a,\,b,\,c}\}$ is projective, and
 408		\begin{align*}
 409			A^x_{a,\,b} \ot \Id_B &\approx_\delta \Id_A \ot B^x_{a,\,b}\,,\\
 410			C^x_{a,\,c} \ot \Id_B &\approx_\delta \Id_A \ot B^x_{a,\,c}\,,
 411		\end{align*}
 412		where $B^x_{a,\,b} = \sum_c B^x_{a,\,b,\,c}$ and $B^x_{a,\,c} = \sum_b B^x_{a,\,b,\,c}$ are the marginals of Definition~\ref{def:povm-conventions}. Then the following approximate commutation relation holds:
 413		\[
 414			[A^x_{a,\,b},\, C^x_{a,\,c}] \ot \Id_B \approx_\delta 0\,.
 415		\]
 416	\end{lemma}
 417	\begin{proof}
 418		\leanok
 419		\uses{fact:add-a-proj, fact:triangle,
 420			lem:distance-left-fiber-contraction,
 421			lem:distance-right-fiber-contraction,
 422			lem:distance-joint-marginal-product,
 423			lem:distance-joint-marginal-product-rev,
 424			lem:distance-opposite-placements-commute, lem:distance-reindex,
 425			lem:distance-congr, lem:distance-congr-sub,
 426			def:distance-swap-last, lem:distance-swap-last-inverse,
 427			lem:distance-symmetry}
 428		Applying Lemma~\ref{fact:add-a-proj} to $C^x_{a,\,c} \ot \Id_B \approx_\delta \Id_A \ot B^x_{a,\,c}$ with the multiplier family $\{A^x_{a,\,b} \ot \Id_B\}$, we have
 429		\begin{equation}\label{eq:commutation-analysis-1}
 430			A^x_{a,\,b}\, C^x_{a,\,c} \ot \Id_B \approx_\delta A^x_{a,\,b} \ot B^x_{a,\,c}\,.
 431		\end{equation}
 432		Similarly, applying Lemma~\ref{fact:add-a-proj} to $A^x_{a,\,b} \ot \Id_B \approx_\delta \Id_A \ot B^x_{a,\,b}$ with the multiplier family $\{\Id_A \ot B^x_{a,\,c}\}$, and using that $\{B^x_{a,\,b,\,c}\}$ is projective,
 433		\begin{equation}\label{eq:commutation-analysis-2}
 434			A^x_{a,\,b} \ot B^x_{a,\,c} \approx_\delta \Id_A \ot B^x_{a,\,c}\, B^x_{a,\,b} = \Id_A \ot B^x_{a,\,b,\,c}\,.
 435		\end{equation}
 436		Combining \eqref{eq:commutation-analysis-1} and \eqref{eq:commutation-analysis-2} via Lemma~\ref{fact:triangle},
 437		\begin{equation}\label{eq:commutation-analysis-3}
